/* Agent dashboard. Reads the same data the client generated by swiping. */
(() => {
  'use strict';

  const $ = (sel) => document.querySelector(sel);
  const el = (tag, cls, text) => {
    const node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined) node.textContent = text;
    return node;
  };

  const state = { leads: [], filter: 'all', query: '', open: new Set() };

  const SCORE_COLOR = { hot: '#ff6ba6', warm: '#21d0a1', cool: '#ffc46b', cold: '#8b95a6' };
  const STATUS_LABEL = {
    started: 'Opened, no swipes',
    swiping: 'Swiping now',
    completed: 'Finished the deck',
    abandoned: 'Dropped out',
  };

  /* --------------------------------------------------------------- auth */

  async function load() {
    const res = await fetch('/api/agent/leads');
    if (res.status === 401) {
      $('#gate').hidden = false;
      $('#desk').hidden = true;
      return;
    }
    const data = await res.json();
    state.leads = data.leads || [];
    $('#gate').hidden = true;
    $('#desk').hidden = false;
    render();
  }

  function wireGate() {
    $('#gate-form').addEventListener('submit', async (e) => {
      e.preventDefault();
      const res = await fetch('/api/agent/session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ passcode: $('#passcode').value }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        $('#gate-error').textContent = data.error || 'That did not work.';
        return;
      }
      $('#passcode').value = '';
      $('#gate-error').textContent = '';
      load();
    });

    $('#btn-logout').addEventListener('click', async () => {
      await fetch('/api/agent/session', { method: 'DELETE' });
      window.location.reload();
    });
    $('#btn-refresh').addEventListener('click', load);
  }

  /* ------------------------------------------------------------ filters */

  function wireToolbar() {
    $('#filters').addEventListener('click', (e) => {
      const chip = e.target.closest('.chip');
      if (!chip) return;
      state.filter = chip.dataset.filter;
      $('#filters').querySelectorAll('.chip').forEach((c) => c.setAttribute('aria-checked', String(c === chip)));
      render();
    });
    $('#search').addEventListener('input', (e) => {
      state.query = e.target.value.trim().toLowerCase();
      render();
    });
  }

  function visibleLeads() {
    return state.leads.filter((lead) => {
      if (state.filter === 'archived') {
        if (!lead.archived) return false;
      } else if (lead.archived) {
        return false;
      }
      if (state.filter === 'qualified' && lead.score.value < 60) return false;
      if (state.filter === 'completed' && lead.status !== 'completed') return false;
      if (state.filter === 'abandoned' && lead.status !== 'abandoned') return false;
      if (state.query) {
        const haystack = [
          lead.contact.name,
          lead.contact.email,
          lead.contact.phone,
          lead.brief.location,
          lead.brief.propertyType,
        ].join(' ').toLowerCase();
        if (!haystack.includes(state.query)) return false;
      }
      return true;
    });
  }

  /* ------------------------------------------------------------- render */

  function render() {
    renderStats();
    const list = $('#leads');
    list.innerHTML = '';
    const leads = visibleLeads();
    $('#empty').hidden = leads.length > 0;
    if (!leads.length && state.leads.length) {
      $('#empty').textContent = 'No leads match that filter.';
      $('#empty').hidden = false;
    } else if (!state.leads.length) {
      $('#empty').textContent = 'Nobody here yet. Send someone the link and watch this fill up.';
    }
    leads.forEach((lead) => list.appendChild(renderLead(lead)));
  }

  function renderStats() {
    const all = state.leads.filter((l) => !l.archived);
    const qualified = all.filter((l) => l.score.value >= 60);
    const finished = all.filter((l) => l.status === 'completed');
    const avg = all.length ? Math.round(all.reduce((s, l) => s + l.score.value, 0) / all.length) : 0;
    const stats = [
      { value: all.length, label: 'Leads in the funnel' },
      { value: qualified.length, label: 'Qualified enough to call' },
      { value: all.length ? `${Math.round((finished.length / all.length) * 100)}%` : '0%', label: 'Finished the deck' },
      { value: avg, label: 'Average score' },
    ];
    const wrap = $('#stats');
    wrap.innerHTML = '';
    stats.forEach((s) => {
      const card = el('div', 'stat');
      card.appendChild(el('div', 'stat-value', String(s.value)));
      card.appendChild(el('div', 'stat-label', s.label));
      wrap.appendChild(card);
    });

    const waiting = all.filter((l) => l.status === 'abandoned' && l.score.value < 60).length;
    $('#desk-sub').textContent = waiting
      ? `${all.length} leads. ${waiting} dropped out before telling you enough.`
      : `${all.length} leads. Newest first.`;
  }

  function renderLead(lead) {
    const wrap = el('article', `lead${lead.archived ? ' is-archived' : ''}${state.open.has(lead.id) ? ' is-open' : ''}`);
    wrap.dataset.id = lead.id;

    /* ---- head ---- */
    const head = el('div', 'lead-head');
    head.setAttribute('role', 'button');
    head.tabIndex = 0;

    const left = el('div');
    const name = el('div', 'lead-name');
    name.appendChild(document.createTextNode(lead.contact.name || 'Unnamed'));
    name.appendChild(el('span', `badge badge-${lead.score.tone}`, lead.score.label));
    name.appendChild(el('span', 'badge badge-status', STATUS_LABEL[lead.status] || lead.status));
    left.appendChild(name);

    const line = el('div', 'lead-line');
    line.innerHTML = `${escapeHtml(lead.contact.email || 'no email')} &middot; <b>${escapeHtml(lead.brief.propertyType || 'type unknown')}</b> in <b>${escapeHtml(lead.brief.location || 'unknown area')}</b> &middot; <b>${escapeHtml(lead.brief.budgetLabel)}</b> &middot; ${lead.progress.done}/${lead.progress.of} cards &middot; ${timeAgo(lead.updatedAt)}`;
    left.appendChild(line);

    const tags = el('div', 'lead-tags');
    lead.wants.slice(0, 5).forEach((w) => tags.appendChild(el('span', 'tag', w.tag)));
    lead.avoid.slice(0, 2).forEach((w) => tags.appendChild(el('span', 'tag tag-no', w.tag)));
    if (tags.children.length) left.appendChild(tags);

    if (lead.dropOff) {
      left.appendChild(el('div', 'dropoff', `Left ${lead.dropOff.stage}, ${lead.dropOff.seen} of ${lead.dropOff.of} cards done.`));
    }

    const right = el('div', 'lead-score');
    right.appendChild(el('div', 'score-num', String(lead.score.value)));
    const bar = el('div', 'score-bar');
    const fill = el('div', 'score-fill');
    fill.style.width = `${lead.score.value}%`;
    fill.style.background = SCORE_COLOR[lead.score.tone];
    bar.appendChild(fill);
    right.appendChild(bar);

    head.append(left, right);
    head.addEventListener('click', () => toggle(lead.id, wrap));
    head.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(lead.id, wrap); }
    });

    wrap.appendChild(head);
    wrap.appendChild(renderBody(lead));
    return wrap;
  }

  function renderBody(lead) {
    const body = el('div', 'lead-body');
    const grid = el('div', 'detail-grid');

    const answers = el('div', 'detail');
    answers.appendChild(el('h4', '', 'What the swipes say'));
    const list = el('ul');
    lead.facets.forEach((facet) => {
      const li = el('li');
      li.appendChild(el('span', 'facet-key', `${facet.key}: `));
      if (facet.wanted.length) li.appendChild(document.createTextNode(facet.wanted.join(', ')));
      if (facet.rejected.length) {
        li.appendChild(document.createTextNode(facet.wanted.length ? ' ' : ''));
        li.appendChild(el('span', 'facet-no', facet.rejected.join(', ')));
      }
      list.appendChild(li);
    });
    if (!lead.facets.length) list.appendChild(el('li', '', 'No swipes yet.'));
    answers.appendChild(list);

    const meta = el('div', 'detail');
    meta.appendChild(el('h4', '', 'Session'));
    const metaList = el('ul');
    [
      ['Started', new Date(lead.createdAt).toLocaleString()],
      ['Last seen', timeAgo(lead.updatedAt)],
      ['Time swiping', `${lead.secondsSpent}s`],
      ['Timing', lead.brief.timelineLabel || 'not given'],
      ['Phone', lead.contact.phone || 'not given'],
      lead.note ? ['Their note', lead.note] : null,
    ].filter(Boolean).forEach(([k, v]) => {
      const li = el('li');
      li.appendChild(el('span', 'facet-key', `${k}: `));
      li.appendChild(document.createTextNode(v));
      metaList.appendChild(li);
    });
    meta.appendChild(metaList);

    grid.append(answers, meta);
    body.appendChild(grid);

    if (lead.likes.length) {
      const liked = el('div', 'detail');
      liked.appendChild(el('h4', '', `Swiped right (${lead.likes.length})`));
      liked.appendChild(thumbs(lead.likes, false));
      body.appendChild(liked);
    }
    if (lead.passes.length) {
      const passed = el('div', 'detail');
      passed.appendChild(el('h4', '', `Swiped left (${lead.passes.length})`));
      passed.appendChild(thumbs(lead.passes, true));
      body.appendChild(passed);
    }

    const summary = el('div', 'detail');
    summary.appendChild(el('h4', '', 'Paste into your CRM'));
    summary.appendChild(el('pre', 'summary', lead.summaryText));
    body.appendChild(summary);

    const notesWrap = el('div', 'detail');
    notesWrap.appendChild(el('h4', '', 'Your notes'));
    const notes = el('textarea', 'notes');
    notes.value = lead.agentNotes || '';
    notes.placeholder = 'Called Tuesday, wants to view the Mill Lane place.';
    notesWrap.appendChild(notes);
    body.appendChild(notesWrap);

    const actions = el('div', 'lead-actions');
    const saveBtn = el('button', 'btn btn-primary btn-sm', 'Save notes');
    const flag = el('span', 'saved-flag', 'Saved');
    saveBtn.addEventListener('click', async () => {
      await patch(lead.id, { agentNotes: notes.value });
      flag.classList.add('is-on');
      setTimeout(() => flag.classList.remove('is-on'), 1400);
    });

    const copyBtn = el('button', 'btn btn-ghost btn-sm', 'Copy summary');
    copyBtn.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(lead.summaryText);
        copyBtn.textContent = 'Copied';
        setTimeout(() => { copyBtn.textContent = 'Copy summary'; }, 1400);
      } catch (_) {
        copyBtn.textContent = 'Copy failed';
      }
    });

    const mail = el('a', 'btn btn-ghost btn-sm', 'Email them');
    mail.href = `mailto:${encodeURIComponent(lead.contact.email || '')}?subject=${encodeURIComponent('Places that match what you swiped')}&body=${encodeURIComponent(`Hi ${(lead.contact.name || '').split(' ')[0]},\n\nThanks for swiping through those. Based on what you liked:\n\n${lead.summaryText}\n\nI have a couple of places that fit. When are you free for a look?\n`)}`;

    const archiveBtn = el('button', 'btn btn-ghost btn-sm', lead.archived ? 'Unarchive' : 'Archive');
    archiveBtn.addEventListener('click', async () => {
      await patch(lead.id, { archived: !lead.archived });
      await load();
    });

    const delBtn = el('button', 'btn btn-danger btn-sm', 'Delete');
    delBtn.addEventListener('click', async () => {
      if (!window.confirm(`Delete ${lead.contact.name || 'this lead'} permanently?`)) return;
      await fetch(`/api/agent/leads/${lead.id}`, { method: 'DELETE' });
      state.open.delete(lead.id);
      await load();
    });

    actions.append(saveBtn, copyBtn, mail, archiveBtn, delBtn, flag);
    body.appendChild(actions);
    return body;
  }

  function thumbs(cards, passed) {
    const wrap = el('div', `thumbs${passed ? ' is-passed' : ''}`);
    cards.forEach((card) => {
      const fig = el('figure');
      const img = el('img');
      img.src = card.image;
      img.alt = card.title;
      img.loading = 'lazy';
      fig.appendChild(img);
      fig.appendChild(el('figcaption', '', card.title));
      wrap.appendChild(fig);
    });
    return wrap;
  }

  async function patch(id, body) {
    const res = await fetch(`/api/agent/leads/${id}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (res.ok) {
      const updated = await res.json();
      const idx = state.leads.findIndex((l) => l.id === id);
      if (idx > -1) state.leads[idx] = updated;
    }
  }

  function toggle(id, node) {
    if (state.open.has(id)) {
      state.open.delete(id);
      node.classList.remove('is-open');
    } else {
      state.open.add(id);
      node.classList.add('is-open');
    }
  }

  /* -------------------------------------------------------------- utils */

  function timeAgo(iso) {
    const diff = Date.now() - new Date(iso).getTime();
    const mins = Math.round(diff / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return `${mins} min ago`;
    const hours = Math.round(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    return `${Math.round(hours / 24)}d ago`;
  }

  function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[c]));
  }

  wireGate();
  wireToolbar();
  load();

  // Keep the desk fresh, but never yank a half-typed note out from under the agent.
  setInterval(() => {
    const active = document.activeElement;
    if (active && active.matches('textarea, input')) return;
    load();
  }, 60000);
})();
